def _sqlite_score(path):
    """Score an existing SQLite file by whether it contains the Prove Am data tables/rows."""
    try:
        import sqlite3 as _sqlite3
        if not os.path.isfile(path): return -1
        con=_sqlite3.connect(path); cur=con.cursor()
        score=0
        for table in ("auth","profiles","friends","posts","messages","stories"):
            try:
                cur.execute("SELECT COUNT(*) FROM "+table)
                n=int(cur.fetchone()[0] or 0)
                score += 100000 if n>0 else 1
                score += min(n,1000)
            except Exception:
                pass
        con.close()
        return score
    except Exception:
        return -1

def _choose_sqlite_path():
    """Prefer the existing populated Prove Am DB; never silently switch to a new empty DB."""
    candidates=[]
    env_path=os.environ.get("SQLITE_DB_PATH","").strip()
    if env_path: candidates.append(env_path)
    candidates += [
        "/data/app.db",
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "app.db"),
        "app.db",
    ]
    # unique paths, preserving order
    seen=set(); candidates=[x for x in candidates if not (x in seen or seen.add(x))]
    existing=[(p,_sqlite_score(p)) for p in candidates if os.path.isfile(p)]
    if existing:
        # Highest score wins; this protects old friends/posts/messages when multiple DB copies exist.
        return max(existing,key=lambda x:x[1])[0]
    # If no DB exists yet, use the stable application directory rather than a cwd-dependent path.
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), "app.db")

SQLITE_DB_PATH = _choose_sqlite_path()
