# Performance indexes: keep feeds, chats and notifications fast as the database grows.
def create_perf_indexes():
    conn=get_conn(); c=conn.cursor()
    indexes=[
        "CREATE INDEX IF NOT EXISTS idx_posts_created ON posts(id DESC)",
        "CREATE INDEX IF NOT EXISTS idx_post_likes_post ON post_likes(post_id)",
        "CREATE INDEX IF NOT EXISTS idx_comments_post ON comments(post_id)",
        "CREATE INDEX IF NOT EXISTS idx_shares_post ON post_shares(post_id)",
        "CREATE INDEX IF NOT EXISTS idx_post_media_post ON post_media(post_id)",
        "CREATE INDEX IF NOT EXISTS idx_messages_pair ON messages(sender,receiver,id)",
        "CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(username,is_read,id)",
        "CREATE INDEX IF NOT EXISTS idx_stories_expiry ON stories(expires_at,id)"
    ]
    for q in indexes:
        try: c.execute(q)
        except Exception: pass
    try: conn.commit()
    except Exception: pass
    conn.close()

create_perf_indexes()

# Fast lookup indexes for the existing Prove Am chat/friend tables.
def create_chat_indexes():
    try:
        conn=get_conn(); c=conn.cursor()
        c.execute("CREATE INDEX IF NOT EXISTS idx_messages_pair_id ON messages(sender,receiver,id DESC)")
        c.execute("CREATE INDEX IF NOT EXISTS idx_messages_receiver_read ON messages(receiver,sender,read)")
        c.execute("CREATE INDEX IF NOT EXISTS idx_friends_pair_status ON friends(sender,receiver,status)")
        conn.commit(); conn.close()
    except Exception:
        try: conn.close()
        except Exception: pass

create_chat_indexes()

def notify(username, ntype, from_user='', text=''):
    if not username or username==from_user: return
    conn=get_conn(); c=conn.cursor()
    try:
        q="INSERT INTO notifications (username,type,from_user,text,created_at,is_read) VALUES (%s,%s,%s,%s,%s,0)" if USE_POSTGRES else "INSERT INTO notifications (username,type,from_user,text,created_at,is_read) VALUES (?,?,?,?,?,0)"
        c.execute(q,(username,ntype,from_user,text,datetime.now().isoformat()))
        conn.commit()
        if sio is not None:
            try:
                sio.emit('notification', {'type':ntype,'from_user':from_user,'text':text}, room='pm:'+username)
            except Exception:
                pass
    except Exception:
        conn.rollback()
    finally: conn.close()

def notify_async(username, ntype, from_user='', text=''):
    threading.Thread(target=notify, args=(username, ntype, from_user, text), daemon=True).start()

def is_friend(a,b):
    if not a or not b: return False
    conn=get_conn(); c=conn.cursor()
    q="SELECT 1 FROM friends WHERE ((sender=%s AND receiver=%s) OR (sender=%s AND receiver=%s)) AND status='accepted' LIMIT 1" if USE_POSTGRES else "SELECT 1 FROM friends WHERE ((sender=? AND receiver=?) OR (sender=? AND receiver=?)) AND status='accepted' LIMIT 1"
    c.execute(q,(a,b,b,a)); ok=bool(c.fetchone()); conn.close(); return ok

def is_blocked(a,b):
    conn=get_conn(); c=conn.cursor()
    q="SELECT 1 FROM blocked_users WHERE blocker=%s AND blocked=%s LIMIT 1" if USE_POSTGRES else "SELECT 1 FROM blocked_users WHERE blocker=? AND blocked=? LIMIT 1"
    c.execute(q,(a,b)); ok=bool(c.fetchone()); conn.close(); return ok

def get_mentions(text):
    import re
    return list(dict.fromkeys(re.findall(r'@([A-Za-z0-9_.-]{3,20})', text or '')))

