@app.route('/login', methods=['POST'])
def login_api():
    data=request.json; u=data.get('username','').strip()[:20]; p=data.get('password','')
    conn=get_conn(); c=conn.cursor()
    c.execute("SELECT password, COALESCE(session_version,1) FROM auth WHERE username=%s" if USE_POSTGRES else "SELECT password, COALESCE(session_version,1) FROM auth WHERE username=?", (u,))
    row=c.fetchone(); conn.close()
    if not row or not check_password_hash(row[0],p): return jsonify({"ok":False,"error":"Wrong pass"})
    # Keep the browser session aligned with the database session version.
    # Older sessions could otherwise be cleared immediately after a deploy,
    # making users/search/messages appear empty even though the data remains.
    db_session_version=int(row[1] or 1)
    session['username']=u
    session['session_version']=db_session_version
    _SESSION_VERSION_CACHE[u]=(db_session_version,time.time())
    return jsonify({"ok":True})

@app.route('/signup', methods=['POST'])
def signup():
    data=request.json or {}; u=data.get('username','').strip()[:20]; p=data.get('password',''); vp=data.get('verify_password','')
    if len(u)<3 or len(p)<3: return jsonify({"ok":False,"error":"Username and password must be at least 3 characters"})
    if p != vp: return jsonify({"ok":False,"error":"Passwords do not match"}),400
    conn=get_conn(); c=conn.cursor()
    c.execute("SELECT 1 FROM auth WHERE username=%s" if USE_POSTGRES else "SELECT 1 FROM auth WHERE username=?", (u,))
    if c.fetchone(): conn.close(); return jsonify({"ok":False,"error":"Taken"})
    if USE_POSTGRES:
        c.execute("INSERT INTO auth VALUES (%s,%s,%s)",(u,generate_password_hash(p),datetime.now().isoformat()))
        c.execute("INSERT INTO profiles (username,pic_url,last_seen) VALUES (%s,%s,%s) ON CONFLICT (username) DO NOTHING",(u,"",datetime.now().isoformat()))
    else:
        c.execute("INSERT INTO auth VALUES (?,?,?)",(u,generate_password_hash(p),datetime.now().isoformat()))
        c.execute("INSERT OR IGNORE INTO profiles (username,pic_url,last_seen) VALUES (?,?,?)",(u,"",datetime.now().isoformat()))
    conn.commit(); conn.close(); session['username']=u; session['session_version']=1; return jsonify({"ok":True})

