@app.route('/api/friends/list')
def api_friends_list():
    me=session.get('username')
    if not me:return jsonify([])
    conn=get_conn(); c=conn.cursor()
    try:
        qf="SELECT sender,receiver FROM friends WHERE (sender=%s OR receiver=%s) AND status='accepted'" if USE_POSTGRES else "SELECT sender,receiver FROM friends WHERE (sender=? OR receiver=?) AND status='accepted'"
        c.execute(qf,(me,me)); friend_rows=c.fetchall()
        qm=("SELECT CASE WHEN sender=%s THEN receiver ELSE sender END AS other, MAX(created_at) "
            "FROM messages WHERE sender=%s OR receiver=%s GROUP BY other") if USE_POSTGRES else ("SELECT CASE WHEN sender=? THEN receiver ELSE sender END AS other, MAX(created_at) "
            "FROM messages WHERE sender=? OR receiver=? GROUP BY other")
        c.execute(qm,(me,me,me)); msg_rows=c.fetchall()
        recent={str(row[0]):str(row[1] or '') for row in msg_rows}

        unread_map={}
        try:
            qu=("SELECT sender,COUNT(*) FROM messages WHERE receiver=%s AND read=0 GROUP BY sender"
                if USE_POSTGRES else
                "SELECT sender,COUNT(*) FROM messages WHERE receiver=? AND read=0 GROUP BY sender")
            c.execute(qu,(me,))
            for us,uc in c.fetchall():
                unread_map[str(us)]=int(uc or 0)
        except Exception:
            unread_map={}

        # Include presence and unread counts in this response so the chat list
        # can update with one request instead of N requests per friend.
        status_map={}
        profile_map={}
        try:
            c.execute("SELECT username,last_seen FROM user_status")
            for su,sl in c.fetchall():
                status_map[str(su)]=(float(sl) if sl is not None else None)
        except Exception:
            status_map={}
        try:
            c.execute("SELECT username,show_last_seen FROM profiles")
            for pu,ps in c.fetchall():
                profile_map[str(pu)]=int(ps if ps is not None else 1)
        except Exception:
            profile_map={}

        now=time.time()
        out=[]
        for sender,receiver in friend_rows:
            other=receiver if sender==me else sender
            if other:
                other=str(other)
                last_seen=status_map.get(other)
                hidden=(profile_map.get(other,1)==0 and other!=me)
                online=(last_seen is not None and (now-last_seen)<40 and not hidden)
                out.append({
                    "username":other,
                    "friend":other,
                    "last_message_at":recent.get(other,''),
                    "online":bool(online),
                    "status_hidden":bool(hidden),
                    "unread_count":int(unread_map.get(other,0))
                })
        out.sort(key=lambda x:x.get('last_message_at',''), reverse=True)
        return jsonify(out)
    finally:
        conn.close()

